// The three faces, self-hosted from their Fontsource packages (SIL Open Font License 1.1).
// next/font preloads them and sizes a metric-matched fallback, so the swap shifts nothing.
import localFont from "next/font/local";

export const display = localFont({
  // Generated by scripts/assets.mjs: Archivo cut to wght 300-500 and wdth 100-125 (27 kB, not 90).
  src: "./generated/archivo-display.woff2",
  variable: "--font-display",
  weight: "300 500",
  display: "swap",
  // Preloaded: the hero headline, the page's LCP element, is set in it.
  declarations: [{ prop: "font-stretch", value: "100% 125%" }],
});

export const ui = localFont({
  src: "../../node_modules/@fontsource-variable/instrument-sans/files/instrument-sans-latin-standard-normal.woff2",
  variable: "--font-ui",
  weight: "400 700",
  display: "swap",
  // Not preloaded: text paints at once in the metric-matched fallback, and the face swaps in.
  preload: false,
});

export const mono = localFont({
  src: [
    {
      path: "../../node_modules/@fontsource/dm-mono/files/dm-mono-latin-400-normal.woff2",
      weight: "400",
    },
    {
      path: "../../node_modules/@fontsource/dm-mono/files/dm-mono-latin-500-normal.woff2",
      weight: "500",
    },
  ],
  variable: "--font-mono",
  display: "swap",
  // Not preloaded: text paints at once in the metric-matched fallback, and the face swaps in.
  preload: false,
});
